ALTER TABLE "billing" ADD CONSTRAINT "billing_state_check" CHECK (("billing"."status" = 'draft' and "billing"."number" is null and "billing"."issued_at" is null and "billing"."issued_by" is null and "billing"."voided_at" is null and "billing"."voided_by" is null and "billing"."void_reason" is null) or ("billing"."status" = 'issued' and "billing"."number" is not null and "billing"."issued_at" is not null and "billing"."voided_at" is null and "billing"."voided_by" is null and "billing"."void_reason" is null) or ("billing"."status" = 'void' and "billing"."number" is not null and "billing"."issued_at" is not null and "billing"."voided_at" is not null and "billing"."void_reason" is not null));